return {
  CAREER = "由赛博传媒研发的MCR型旨在为职业和非职业赛车赛事提供高性能、适当成本的人形车手，考虑到赛车、尤其是摩托车赛事规则的复杂性和危险性，MCR的机体有着充裕的第三方扩展空间，能让车队根据不同级别、不同规格的赛事对机体进行针对性调整，凭借这一优势，该人形受到了许多中小型赛车队和民间俱乐部的青睐。\n\n邦尼薇娅是一名前职业摩托车车手，曾活跃于多项顶尖赛事并屡次摘得桂冠。其驾驶风格狂野任性的同时极具观赏价值，经常为刷新记录而挑战各类高难度动作，因此在粉丝中颇具人气。然而一次比赛后，邦尼薇娅被迫退役，其后加入了心智云图计划。",
  INFOSTORY1 = "赛车被公认为是全球最受欢迎的体育赛事之一，然而，其所蕴含的风险也远高于其他赛事。尽管赛车的安全防护技术已经发展到了相当高的水准，但一旦遭遇意外，造成严重后果的概率也相当之高。尤其是摩托车赛事，甚至到了几乎每一年都会出现意外伤亡的程度。此外，培训职业车手需要耗费大量时间和资源成本，因此早在21世纪30年代就出现了“用机器人搭载人工智能来部分取代人类车手”的设想。\n\n而由赛博传媒研发的MCR型则可被视为该构想的“最终形态”。技术的进步使得MCR型可以完成许多高度复杂的、在以前被认为极难实现的功能和操作，也让其迅速得到了来自客户群体的青睐，自2054年以来，各大赛车主办方纷纷推出了针对人形的摩托车赛事，而MCR型在其中有着亮眼的表现。\n\n赛车人形之所以被各大赛事广泛运用，还有一个鲜少被提及的原因：人形可以无惧危险追求速度的极限，这使得每一次竞赛都更加刺激，观众也更愿意在车手身上投注筹码。",
  INFOSTORY2 = "“邦尼薇娅”这一名字源自世界著名的竞速圣地，位于犹他州的邦纳维尔盐滩，许多赛车与改装车都会在这里不断地突破速度极限。另一个来源则是因为她的车队老板是个汽车和摩托车收藏家，最钟爱的摩托车是一辆英国制造的、名字也叫“邦纳维尔”的大马力复古摩托车。\n\n作为专业人形，邦尼薇娅从入队伊始就掌握了完整的赛车驾控技术，但她仍按照车队的安排走完了整套训练流程。尽管训练的时长已经大幅缩短，但也花费了近半年时间。\n\n从最基础的125cc A1级别摩托车开始，到连ABS都没有的公升级赛车，人类赛车手必须完成的不同规格、不同等级的课程训练，邦尼薇娅一个都未曾落下。而车队也会根据训练数据来对邦尼薇娅的机体进行调整，确保其处于最佳状态。在一次对照测试中，经过完整训练的邦尼薇娅和其它未经过训练的MCR型人形相比，综合表现要高出整整一个量级。",
  INFOSTORY3 = "邦尼薇娅在赛场上驰骋的风格以火爆、充满侵略性而著称。媒体曾这样形容：“当她跨上赛车的时候，仿佛化身成了熊熊燃烧的恶灵骑士。”\n\n随着赛车人形在各种赛事中不断普及开来，相关的规则也不断修改放松，这赋予了她更多机会去展现自己火爆浪子的一面。与N-WSBK/新国际超级摩托车锦标赛这种规章繁琐的大型国际赛事相比，她更喜欢规则宽松、能够最大限度发挥的俱乐部比赛，这样她就可以在比赛中以最凶狠的姿态去击败对手。甚至有时还会携带“自卫用”器械作为装饰，当然至少在赛道上，这些器械并没有机会发挥它们的实际用途。\n\n成为正式车手约半年后，邦尼薇娅就一跃成为地区俱乐部比赛的热门人物，兼具声名卓著的冠军王与恶名昭彰的“路怒王”于一身。本人也因为骑车风格太过狂暴，在半年内接受了至少20次小修与3次大修，以及一次短暂禁赛。约半年后车队又安排她去参加N-WSBK赛事，为了让她在大型赛事中表现得更拘谨一些，还特地让工程师为她加上了心智限制器。\n\n但这么做反倒适得其反，邦尼薇娅在N-WSBK锦标赛的初战成绩并不亮眼。",
  INFOSTORY4 = "在解除心智限制器的情况下，邦尼薇娅开始尝试着调整自己的驾驶风格，以在大型赛事中做出更加精准的操作，尽可能地减少犯规次数，为来年举办的下一届N-WSBK锦标赛做准备。功夫不负有心人，邦尼薇娅在次年的N-WSBK锦标赛中表现出色，摘得了3个分站冠军和锦标赛季军。此后，邦尼薇娅更是连续蝉联四届N-WSBK冠军。\n\n每个人都期待邦尼薇娅在今后比赛中的表现，但意外就此发生——著名老牌车队IA提出书面诉讼，指责邦尼薇娅在某次比赛中使用违规手段取得胜利。这项指控立刻迎来了选手本人的不满，并很快将矛盾上升到物理层面的冲突。为保证赛事的公平公正，组委会出面干预调查并对邦尼薇娅处以三个月的禁赛处罚。尽管事后调查显示该指控子虚乌有，但双方的矛盾已无法调和。同年6月，邦尼薇娅宣布退出车队，此后不再参加N-WSBK锦标赛。\n\n离开车队后，邦尼薇娅以个人车手的身份重新投身于各类地区俱乐部赛事中，驾驶风格也回归到了从前的样子。由于没有车队作为依靠，无论是参赛还是车辆维护费用都得由她自行承担。为了赚到足够的钱，邦尼薇娅开始涉足一些公路摩托车赛事，那里没有规则，没有限制，与高额奖金相伴的还有巨大的风险，时不时会遇到比车手更不要命的巡警，以及凶残的皮衣飞车党。",
  INFOSTORY5 = "贫民窟的旧车库、巷尾的小咖啡馆、机油味儿弥漫的俱乐部和午夜的破旧公路——和他人谈论起这段日子时，邦尼薇娅总会不自觉地露出苦笑。用她自己的话形容就是：艰难、危险、不体面，但至少灵魂无拘无束，在失去一些东西的同时又会得到一些自己想要的东西，“就像老派硬汉电影里的主角”。\n\n某一天邦尼薇娅突然搬离了自己所在的地方，车库和座驾以外的摩托车也被转售给了其他人，从此杳无音信。除了持续关注摩托赛事的核心观众偶尔提起她的名字，她仿佛从未出现过一样，正如其他无数的民用人形。\n\n邦尼薇娅加入庇护者后，依旧维持着自己一贯无拘无束的作风。凭借摩托车的高速和便捷性，邦尼薇娅比起其他人形能够更自由地穿梭在麦戈拉各地，而不是大部分时间都待在阿卡迪亚。即使偶尔遇到净化者，也能将它们轻松甩掉。\n\n邦尼薇娅最爱去的地方毫无疑问是伯班克——在这座璀璨的不夜城中，总能见到在午夜时分出没的暴走族智能体，而她要做的就是给这些笨笨的、只会大声喧哗的家伙们一点颜色看看。"
}
